inputs.select:
@concat(
  ',',
  '"',
  replace(coalesce(item()?['Title'], ''), '"', concat(decodeUriComponent('%5C'), '"')),
  '":"',
  replace(
    replace(
      replace(
        replace(
          coalesce(
            if(
              equals(variables('OperationMode'), 'PROD_NODMP'),
              item()?['Value_PROD_NODMP'],
              if(
                equals(variables('OperationMode'), 'PROD_DMP'),
                item()?['Value_x002d_PROD_x0028_DMP_x0029'],
                if(
                  equals(variables('OperationMode'), 'SIMU_NODMP'),
                  coalesce(item()?['Value_x002d_SIMU_x0028_NODMP_x0029'], item()?['Value_x002d_SIMU_x0028_NODMP_x00']),
                  item()?['Value_x002d_SIMU_x0028_DMP_x0029']
                )
              )
            ),
            ''
          ),
          decodeUriComponent('%5C'),
          concat(decodeUriComponent('%5C'), decodeUriComponent('%5C'))
        ),
        '"',
        concat(decodeUriComponent('%5C'), '"')
      ),
      decodeUriComponent('%0D'),
      ''
    ),
    decodeUriComponent('%0A'),
    concat(decodeUriComponent('%5C'), 'n')
  ),
  '"'
)

value.KeyOutput:
@{if(
  equals(coalesce(first(body('FILTER_Config_CurrentOperationMode'))?['CurrentValue'], ''), variables('RequestedAction')),
  'No change - requested operational mode already active',
  concat('Switch from ', coalesce(first(body('FILTER_Config_CurrentOperationMode'))?['CurrentValue'], '(unknown)'), ' to ', variables('RequestedAction'))
)}

parameters.item/KeyOutput:
@if(
  equals(coalesce(first(body('FILTER_Config_CurrentOperationMode'))?['CurrentValue'], ''), variables('RequestedAction')),
  'No change - requested operational mode already active',
  concat('Switch from ', coalesce(first(body('FILTER_Config_CurrentOperationMode'))?['CurrentValue'], '(unknown)'), ' to ', variables('RequestedAction'))
)

parameters.item/LastFailureMessage:
@if(
  equals(variables('AuditOutcome'), 'Succeeded'),
  first(body('GET_StatusRow_Agent_05')?['value'])?['LastFailureMessage'],
  concat(
    'Agent 5 did not complete with Succeeded. AuditOutcome=',
    variables('AuditOutcome'),
    ' | RequestedAction=',
    variables('RequestedAction')
  )
)

parameters.item/StatusMessage:
@if(
  equals(variables('AuditOutcome'), 'Succeeded'),
  concat(
    'Operating State updated successfully. NewOperationMode=',
    variables('RequestedAction')
  ),
  concat(
    'Operating State update failed or ended without confirmed success. AuditOutcome=',
    variables('AuditOutcome'),
    ' | RequestedAction=',
    variables('RequestedAction')
  )
)
